import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../core/format/byte_format.dart';
import '../../core/l10n/localization_extensions.dart';
import '../../core/theme/app_theme.dart';
import '../../core/widgets/app_page_title.dart';
import '../../domain/models/node_modules_entry.dart';
import '../../providers/node_modules_providers.dart';
import '../../providers/infra_providers.dart';
import 'package:intl/intl.dart';

class NodeModulesPage extends ConsumerStatefulWidget {
  const NodeModulesPage({super.key});

  @override
  ConsumerState<NodeModulesPage> createState() => _NodeModulesPageState();
}

class _NodeModulesPageState extends ConsumerState<NodeModulesPage> {
  static const _staleDays = 30;
  bool _deleting = false;

  @override
  Widget build(BuildContext context) {
    final settings = ref.watch(settingsProvider);
    final async = ref.watch(nodeModulesProvider);

    return Scaffold(
      appBar: AppBar(
        title: AppPageTitle(
          title: context.l10n.nodeModules,
          subtitle: context.l10n.nodeModulesSubtitle,
        ),
        actions: [
          TextButton.icon(
            onPressed: () => ref.invalidate(nodeModulesProvider),
            icon: const Icon(Icons.refresh_rounded),
            label: Text(context.l10n.scan),
          ),
          const SizedBox(width: 8),
        ],
      ),
      body: Column(
        children: [
          _Header(
            lruEnabled: settings.lruEnabled,
            roots: settings.nodeModulesRoots,
            onLruChanged: (v) {
              final notifier = ref.read(settingsProvider.notifier);
              notifier.update(settings.copyWith(lruEnabled: v));
            },
          ),
          const Divider(height: 1),
          Expanded(
            child: async.when(
              loading: () => const Center(child: CircularProgressIndicator()),
              error: (e, _) =>
                  Center(child: Text(context.l10n.errorMessage(e))),
              data: (entries) {
                if (entries.isEmpty) {
                  return Center(
                    child: Padding(
                      padding: const EdgeInsets.all(24),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Icon(
                            Icons.folder_off_rounded,
                            size: 56,
                            color: Theme.of(
                              context,
                            ).colorScheme.onSurfaceVariant,
                          ),
                          const SizedBox(height: 12),
                          Text(
                            context.l10n.noNodeModulesFound,
                            style: TextStyle(
                              color: Theme.of(
                                context,
                              ).colorScheme.onSurfaceVariant,
                            ),
                          ),
                          const SizedBox(height: 8),
                          Text(
                            context.l10n.addNodeModulesRoots,
                            style: TextStyle(
                              fontSize: 12,
                              color: Theme.of(
                                context,
                              ).colorScheme.onSurfaceVariant,
                            ),
                          ),
                        ],
                      ),
                    ),
                  );
                }

                final shown = _lruSort(entries, settings.lruEnabled);
                final total = entries.fold(0, (s, e) => s + e.sizeBytes);
                final selectedBytes = entries
                    .where((e) => e.selected)
                    .fold(0, (s, e) => s + e.sizeBytes);

                return ListView(
                  padding: const EdgeInsets.all(16),
                  children: [
                    Text(
                      context.l10n.nodeModulesSummary(
                        entries.length,
                        formatBytes(total, locale: context.localeName),
                        formatBytes(selectedBytes, locale: context.localeName),
                      ),
                      style: TextStyle(
                        color: Theme.of(context).colorScheme.onSurfaceVariant,
                        fontSize: 13,
                      ),
                    ),
                    const SizedBox(height: 8),
                    ...shown.map(
                      (e) => _EntryTile(
                        entry: e,
                        stale: e.lastModifiedAt.isBefore(
                          DateTime.now().subtract(
                            const Duration(days: _staleDays),
                          ),
                        ),
                        onToggle: (v) {
                          setState(() => e.selected = v);
                        },
                      ),
                    ),
                  ],
                );
              },
            ),
          ),
          if (async.valueOrNull?.any((e) => e.selected) == true)
            _CleanBar(
              selectedBytes: async.valueOrNull!
                  .where((e) => e.selected)
                  .fold(0, (s, e) => s + e.sizeBytes),
              count: async.valueOrNull!.where((e) => e.selected).length,
              deleting: _deleting,
              onDelete: () => _delete(context, ref),
            ),
        ],
      ),
    );
  }

  // When LRU is on, only folders not used recently are auto-selected.
  List<NodeModulesEntry> _lruSort(
    List<NodeModulesEntry> entries,
    bool lruEnabled,
  ) {
    final sorted = [...entries]
      ..sort((a, b) => a.lastModifiedAt.compareTo(b.lastModifiedAt));
    if (lruEnabled) {
      final cutoff = DateTime.now().subtract(const Duration(days: _staleDays));
      for (final e in sorted) {
        e.selected = e.lastModifiedAt.isBefore(cutoff);
      }
    }
    return sorted;
  }

  Future<void> _delete(BuildContext ctx, WidgetRef ref) async {
    final entries =
        ref
            .read(nodeModulesProvider)
            .valueOrNull
            ?.where((e) => e.selected)
            .toList() ??
        [];
    if (entries.isEmpty) return;
    final total = entries.fold(0, (s, e) => s + e.sizeBytes);
    final l10n = ctx.l10n;

    final confirm = await showDialog<bool>(
      context: ctx,
      builder: (c) => AlertDialog(
        title: Text(l10n.deleteNodeModulesTitle),
        content: Text(
          l10n.deleteNodeModulesContent(
            entries.length,
            formatBytes(total, locale: ctx.localeName),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(c, false),
            child: Text(l10n.cancel),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(c, true),
            style: FilledButton.styleFrom(
              backgroundColor: Theme.of(context).colorScheme.error,
            ),
            child: Text(l10n.delete),
          ),
        ],
      ),
    );
    if (confirm != true) return;

    setState(() => _deleting = true);
    final repo = ref.read(nodeModulesRepositoryProvider);
    await repo.delete(entries);
    setState(() => _deleting = false);
    ref.invalidate(nodeModulesProvider);
  }
}

class _Header extends StatelessWidget {
  final bool lruEnabled;
  final List<String> roots;
  final ValueChanged<bool> onLruChanged;

  const _Header({
    required this.lruEnabled,
    required this.roots,
    required this.onLruChanged,
  });

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
      child: Row(
        children: [
          Icon(Icons.timelapse_rounded, color: AppPalette.warningFor(context)),
          const SizedBox(width: 10),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  context.l10n.lruTitle,
                  style: const TextStyle(
                    fontWeight: FontWeight.w600,
                    fontSize: 14,
                  ),
                ),
                const SizedBox(height: 2),
                Text(
                  lruEnabled
                      ? context.l10n.lruEnabledDescription
                      : context.l10n.lruDisabledDescription,
                  style: TextStyle(
                    fontSize: 12,
                    color: Theme.of(context).colorScheme.onSurfaceVariant,
                  ),
                ),
              ],
            ),
          ),
          Switch(value: lruEnabled, onChanged: onLruChanged),
        ],
      ),
    );
  }
}

class _EntryTile extends StatelessWidget {
  final NodeModulesEntry entry;
  final bool stale;
  final ValueChanged<bool> onToggle;

  const _EntryTile({
    required this.entry,
    required this.stale,
    required this.onToggle,
  });

  @override
  Widget build(BuildContext context) {
    return Card(
      margin: const EdgeInsets.only(bottom: 8),
      child: CheckboxListTile(
        value: entry.selected,
        onChanged: (v) => onToggle(v ?? false),
        title: Row(
          children: [
            Flexible(
              child: Text(
                entry.projectName,
                style: const TextStyle(fontWeight: FontWeight.w500),
                overflow: TextOverflow.ellipsis,
              ),
            ),
            if (stale)
              Container(
                margin: const EdgeInsets.only(left: 8),
                padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                decoration: BoxDecoration(
                  color: AppPalette.warningFor(context).withValues(alpha: 0.1),
                  borderRadius: BorderRadius.circular(4),
                ),
                child: Text(
                  context.l10n.idle,
                  style: TextStyle(
                    fontSize: 10,
                    color: AppPalette.warningFor(context),
                  ),
                ),
              ),
          ],
        ),
        subtitle: Text(
          '${entry.path}\n${context.l10n.lastUsed(DateFormat.yMd(context.localeName).format(entry.lastModifiedAt))}',
          style: const TextStyle(fontSize: 11),
          maxLines: 2,
          overflow: TextOverflow.ellipsis,
        ),
        secondary: Text(
          formatBytes(entry.sizeBytes, locale: context.localeName),
          style: const TextStyle(fontWeight: FontWeight.w600),
        ),
        controlAffinity: ListTileControlAffinity.leading,
      ),
    );
  }
}

class _CleanBar extends StatelessWidget {
  final int selectedBytes;
  final int count;
  final bool deleting;
  final VoidCallback onDelete;

  const _CleanBar({
    required this.selectedBytes,
    required this.count,
    required this.deleting,
    required this.onDelete,
  });

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 16),
      decoration: BoxDecoration(
        color: Theme.of(context).colorScheme.surfaceContainerLow,
        border: Border(top: BorderSide(color: Theme.of(context).dividerColor)),
      ),
      child: Row(
        children: [
          Text(
            context.l10n.selectedSummary(
              count,
              formatBytes(selectedBytes, locale: context.localeName),
            ),
            style: const TextStyle(fontWeight: FontWeight.w600),
          ),
          const Spacer(),
          FilledButton.icon(
            onPressed: deleting ? null : onDelete,
            icon: const Icon(Icons.delete_rounded),
            label: Text(context.l10n.deleteSelected),
            style: FilledButton.styleFrom(
              backgroundColor: Theme.of(context).colorScheme.error,
            ),
          ),
        ],
      ),
    );
  }
}
